class Solution:
    def friendRequests(self, n, restrictions, requests):
        # DSU boilerplate
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]  # Path compression
                x = parent[x]
            return x

        def union(x, y):
            px, py = find(x), find(y)
            if px != py:
                parent[py] = px

        ans = []
        for u, v in requests:
            pu, pv = find(u), find(v)
            if pu == pv:
                ans.append(True)  # already friends
                continue

            # Check all restrictions: Will any restricted pair be in the same component?
            can_union = True
            for a, b in restrictions:
                pa, pb = find(a), find(b)
                # If this union merges pu & pv, will either restriction be violated?
                # That is, (a in u's group and b in v's group) or vice versa,
                # after union they would be together.
                if ( (pa == pu and pb == pv) or (pa == pv and pb == pu) ):
                    can_union = False
                    break
            if can_union:
                union(u, v)
                ans.append(True)
            else:
                ans.append(False)
        return ans
